import java.util.List;
import java.util.stream.Collectors;

public class LambdaDemo {
    public static void main(String[] args) {
        var orders = List.of("laptop", "phone", "tablet", "monitor");

        // Old way: anonymous class for Predicate
        var filteredOld = orders.stream()
            .filter(new java.util.function.Predicate<String>() {
                public boolean test(String item) {
                    return item.length() > 5;  // verbose boilerplate
                }
            })
            .collect(Collectors.toList());

        // Lambda way: concise functional syntax
        var filteredNew = orders.stream()
            .filter(item -> item.length() > 5)  // implements Predicate<String>
            .map(String::toUpperCase)            // method reference
            .collect(Collectors.toList());

        System.out.println(filteredNew);  // [LAPTOP, TABLET, MONITOR]
    }
}

import java.util.List;
import java.util.function.Predicate;

public class EffectivelyFinalDemo {
    private int instanceCounter = 0;  // instance variable — OK to modify

    public void processOrders(List<String> orders) {
        int minLength = 5;  // effectively final — never reassigned
        String prefix = "ORDER-";  // effectively final

        // Lambda captures minLength and prefix — compiles fine
        orders.stream()
            .filter(order -> order.length() >= minLength)
            .forEach(order -> {
                System.out.println(prefix + order);
                instanceCounter++;  // modifying instance variable is allowed
            });

        // minLength = 6;  // COMPILE ERROR if uncommented — breaks effectively final

        // This would fail: local variable modified after capture
        int attemptCount = 0;
        Predicate<String> validator = s -> {
            // attemptCount++;  // COMPILE ERROR — can't modify captured local
            return s.length() > minLength;
        };
    }
}

import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.function.Function;

public class LambdaExceptionDemo {

    public void processFiles(List<String> filePaths) {
        // COMPILE ERROR: Function doesn't declare IOException
        // var contents = filePaths.stream()
        //     .map(path -> Files.readString(Path.of(path)))  // throws IOException
        //     .toList();

        // Workaround 1: wrap in unchecked exception
        var contents = filePaths.stream()
            .map(path -> {
                try {
                    return Files.readString(Path.of(path));
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read: " + path, e);  // wrap it
                }
            })
            .toList();

        // Workaround 2: custom functional interface
        var parsed = filePaths.stream()
            .map(unchecked(path -> Files.readString(Path.of(path))))  // utility wrapper
            .toList();
    }

    // Utility to convert throwing function
    static <T, R> Function<T, R> unchecked(ThrowingFunction<T, R> f) {
        return t -> {
            try {
                return f.apply(t);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        };
    }

    @FunctionalInterface
    interface ThrowingFunction<T, R> {
        R apply(T t) throws Exception;
    }
}

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class VariableAccessDemo {
    private int processedCount = 0;       // instance variable
    private List<String> results;         // instance variable
    private static int totalProcessed = 0;  // static variable

    public void processOrders(List<String> orders) {
        int minLength = 5;  // local variable — must be effectively final

        orders.stream()
            .filter(order -> order.length() >= minLength)  // read local — OK
            .forEach(order -> {
                processedCount++;         // modify instance variable — perfectly fine
                totalProcessed++;         // modify static variable — also fine
                results.add(order);       // modify instance collection — no problem

                // minLength++;  // COMPILE ERROR — can't modify local variable
            });

        System.out.println("Processed: " + processedCount);
    }

    public static void logActivity(List<String> activities) {
        var counter = new AtomicInteger(0);  // workaround for local modification

        activities.forEach(activity -> {
            totalProcessed++;           // static in static method — fine
            counter.incrementAndGet();  // wrapped local counter — workaround
            // this.processedCount++;   // COMPILE ERROR — can't access instance from static
        });
    }
}

import java.util.List;

public class OrderProcessor {
    private String processorName = "MainProcessor";

    public void processWithLambda(List<String> orders) {
        orders.forEach(order -> {
            // 'this' refers to OrderProcessor instance
            System.out.println(this.processorName + " processing: " + order);
            this.logActivity(order);  // calling enclosing class method directly
        });
    }

    public void processWithAnonymousClass(List<String> orders) {
        orders.forEach(new java.util.function.Consumer<String>() {
            private String anonymousName = "AnonymousConsumer";

            @Override
            public void accept(String order) {
                // 'this' refers to the anonymous Consumer instance
                System.out.println(this.anonymousName);  // anonymous class field

                // Must use OuterClass.this to access enclosing instance
                System.out.println(OrderProcessor.this.processorName);
                OrderProcessor.this.logActivity(order);  // explicit outer reference
            }
        });
    }

    private void logActivity(String order) {
        System.out.println("Logged: " + order);
    }
}

import java.util.List;
import java.util.function.Predicate;

public class LambdaCompilationDemo {

    public void filterOrders(List<String> orders) {
        // Source code: lambda expression
        Predicate<String> isLongOrder = order -> order.length() > 10;

        // Compiler transforms lambda body to a static method (conceptual view):
        // private static boolean lambda$filterOrders$0(String order) {
        //     return order.length() > 10;
        // }

        // Compiler generates invokedynamic instruction (pseudo-bytecode):
        // invokedynamic #0 : test()Ljava/util/function/Predicate;
        //   Bootstrap: LambdaMetafactory.metafactory(
        //     MethodHandles.lookup(),
        //     "test",
        //     signature of functional interface,
        //     method handle to lambda$filterOrders$0
        //   )

        var result = orders.stream()
            .filter(isLongOrder)  // at runtime: metafactory creates Predicate implementation
            .toList();

        // Key difference from anonymous class:
        // - No OrderProcessor$1.class file generated
        // - No new object allocated if lambda is stateless
        // - Implementation strategy can change in future JVM versions
    }
}
